WITH with_dims AS (SELECT e.*, p.amount FROM shipments e JOIN orders p ON e.order_id = p.id) SELECT DATE_TRUNC('YEAR', shipped_date) AS year_start, DATE_TRUNC('QUARTER', shipped_date) AS quarter_start, COUNT(*) AS cnt, SIZE(COLLECT_SET(carrier)) AS num_carriers, SIZE(COLLECT_SET(status)) AS num_status, AVG(cost) FILTER (WHERE status = 'LOST') AS lost_avg_cost, APPROX_PERCENTILE(amount, 0.95) AS amount_p95, COUNT(DISTINCT carrier) AS distinct_carriers, GROUPING_ID() AS grouping_level FROM with_dims GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', shipped_date), DATE_TRUNC('QUARTER', shipped_date)), (DATE_TRUNC('YEAR', shipped_date))) ORDER BY num_status DESC NULLS FIRST
